#include "streaming/streaming.hpp"
#include <cassert>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <iterator>
int main(){using namespace kg::stream;Config c;c.activeRadius=1;c.cacheLimit=10;c.resolution=17;assert(validConfig(c));assert(keyAt(-0.1,-64,64)==(ChunkKey{-1,-1}));assert(keyAt(64,0,64)==(ChunkKey{1,0}));assert(heightAt(12,31,c.seed)==heightAt(12,31,c.seed));assert(caveField(10,5,2,c.seed)==caveField(10,5,2,c.seed));assert(caveSolid(1,2,3,c.seed,1));auto m=buildTerrainChunk({0,0},c,0);assert(m.vertices.size()==289&&m.indices.size()==1536);auto adjacent=buildTerrainChunk({1,0},c,0);for(int z=0;z<17;++z){auto a=m.vertices[size_t(z)*17+16].p;auto b=adjacent.vertices[size_t(z)*17].p;assert(a.x==b.x&&a.y==b.y&&a.z==b.z);}auto mask=buildCaveMask({0,0},c,0);assert(mask.size()==m.vertices.size());Chunk ch;ch.key={0,0};ch.mesh=m;ch.caveMask=mask;assert(fingerprint(ch)==fingerprint(ch));assert(lodForDistance(0,64)==0);assert(lodForDistance(128,64)==1);assert(desiredChunks(0,0,c).size()==9);assert(intersectsViewRadius({0,0},32,32,1,64));auto bridge=buildBridge({0,0,0},{100,0,0},12,20);assert(bridge.vertices.size()==8&&bridge.indices.size()==36);ChunkStreamer s(c);s.update(0,0);assert(s.stats().generated==9&&s.stats().resident==9);auto hash=s.find({0,0})->fingerprint;s.update(0,0);assert(s.stats().cacheHits==9&&s.find({0,0})->fingerprint==hash);s.update(192,0);assert(s.stats().resident<=10&&s.stats().evictions>0);auto p=std::filesystem::temp_directory_path()/"kartgib_drop08_manifest.json";exportChunkManifest(s,p);std::ifstream in(p);std::string data((std::istreambuf_iterator<char>(in)),{});assert(data.find("fingerprint")!=std::string::npos);std::filesystem::remove(p);Config bad=c;bad.cacheLimit=1;assert(!validConfig(bad));std::cout<<"STREAMING_TESTS_PASS\n";}
